import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "returns");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build base query - parameterized for type
        String baseQuery = "SELECT * FROM reports WHERE report_type = '" + reportType + "'";

        // Date range handling
        if (dateRange != null && dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            String[] parts = dateRange.split("_");
            baseQuery += " AND created_at BETWEEN '" + parts[0] + "' AND '" + parts[1] + "'";
        }

        // Sort column - attempt at validation
        if (sortCol != null) {
            // Only allow alphanumeric and underscore
            if (sortCol.matches("[a-zA-Z_]+")) {
                baseQuery += " ORDER BY " + sortCol;
            }
        }

        // Custom filter - VULNERABLE: direct concatenation
        if (customFilter != null && !customFilter.isEmpty()) {
            baseQuery += " AND (" + customFilter + ")";
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(baseQuery)) {

            StringBuilder json = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnName(i)).append("\": ");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            // Log full error for debugging
            resp.setStatus(500);
            out.print("{\"error\": \"" + e.getMessage() + "\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Delegate to GET for report generation
        doGet(req, resp);
    }
}
